// NASTRAN Voigt order for 3D elasticity:
// strain = {eps_xx, eps_yy, eps_zz, gamma_yz, gamma_xz, gamma_xy}
// D matrix diagonal: D(1,1)=D(2,2)=D(3,3)=E*(1-nu)/((1+nu)*(1-2*nu))
// D(4,4)=D(5,5)=D(6,6)=G (shear modulus)
// Off-diagonal: D(1,2)=D(1,3)=D(2,3)=E*nu/((1+nu)*(1-2*nu))

// H matrix (4x4)
Eigen::Matrix4d H;
for(int i=0; i<4; i++) H.row(i) << 1.0, x[i], y[i], z[i];
double detH = H.determinant();
Eigen::Matrix4d Hinv = H.inverse();
double V = std::abs(detH) / 6.0;

// B matrices (6x3 per node)
for(int n=0; n<4; n++) {
  double b1 = Hinv(1,n); // dN/dx
  double b2 = Hinv(2,n); // dN/dy
  double b3 = Hinv(3,n); // dN/dz
  B[n] << b1, 0,  0,
          0,  b2, 0,
          0,  0,  b3,
          0,  b3, b2,
          b3, 0,  b1,
          b2, b1, 0;
}
// K = sum over i,j: V * B[i].T * D * B[j]

// Assembly
Eigen::Matrix<double,12,12> K = Eigen::Matrix<double,12,12>::Zero();
for(int i=0; i<4; i++) {
  for(int j=0; j<4; j++) {
    Eigen::Matrix3d Kij = V * (B[i].transpose() * D * B[j]);
    K.block<3,3>(3*i, 3*j) = Kij;
  }
}

// Gauss points for arc integration (4-point)
// For each Gauss point at angle phi:
//   1. Compute T(phi) - force transfer matrix
//   2. Compute f_section - cross-section flexibility
//   3. Accumulate: F += weight * T^T * f * T * R
// Finally: K_local = F.inverse()
// Transform to global: K_global = R^T * K_local * R

// FIXED: Swap indices - use B[j]^T * D * B[i] instead of B[i]^T * D * B[j]
            Matrix3d Kij = volume * (B[j].transpose() * D * B[i]);
            K.block<3, 3>(3 * i, 3 * j) = Kij;
        }
    }

    // Ensure symmetry (numerical roundoff)

// Compute stiffness: K = t * area * B^T * D * B
        Matrix<double, 6, 6> K = t * area * (B.transpose() * D * B);

        return K;
    }
};

